/* Scrolls the four hue values of a moby's effect and spawns a coloured streak for each. Adapted from Lombyte's project (GPL-3.0) for PAL: src/overlays/shared/gameplay_vendor_002df730.c, FUN_L00_002e0788. */
void emit_moby_color_cycling_particles(char *p) {
    float v[8];
    FxData *m = ((FxData *)((Moby *)p)->pvars);
    float *a;
    int *t;
    int i, j, c, k;
    float f, g;
    j = 0;
    p += 0x10;
    FastVecSub(v, g_debug_camera, (float *)p);
    t = m->t;
    a = m->a;
    vec_scale_to_length(v, v, -0.3f);
    vec_scale_to_length(&v[4], v, 0.1f);
    FastVecAdd(v, v, p);
    for (i = 3; i >= 0; i--) {
        f = *a + m->b[j];
        *a = f;
        if (f >= 255.0f) {
            *a = f - 255.0f;
        } else if (f <= 0.0f) {
            *a = f + 255.0f;
        }
        if (fast_dec_timer(t)) {
            m->t[j] = scale_ticks(255);
        }
        t++;
        g = IntToFloat(scale_ticks(255) - m->t[j]);
        g = g / (float)scale_ticks(255);
        c = FastTweenColor(0x4040FFFF, 0x1040FFFF, absolute_float(0.5f - g));
        k = truncate_float_to_s32(*a++);
        PartType59Spawn_v(m->c[j], v, c, k, 0x35, 1, 2, 0);
        j++;
        FastVecAdd(v, v, &v[4]);
    }
}
