                p->fC = 120000.0f;
                p->fA = scale_ticks(4);
                q->f10 = one / IntToFloat(p->fA);
                q->f18 = 0x7F7F7F;
                if (beam_spark_style_r[idx] == 1)
                    q->f16 = 1;
