/* Scrolls and draws the two panes of each active slot (3 slots). */
void draw_active_beam_slots(char *m) {
    int *d = ((int *)((Moby *)m)->pvars);
    int i;
    VU1_addGSregister(0x47, 0x51001);
    for (i = 0; i < 3; i++) {
        float f;
        int a, b;
        int k, k1;
        if (beam_slot_id[i] == 0 || beam_slot_state[i] < 2)
            continue;
        k = i << 1;
        k1 = k + 1;
        f = beam_texture_scroll_f[i] - frame_scale * 0.2f;
        beam_texture_scroll_f[i] = f;
        if (f <= -8.0f)
            beam_texture_scroll_f[i] = f + 8.0f;
        draw_beam_endpoint_quads_with_glow(beam_slot_id[i], i);
        a = d[1] + 0x28;
        b = d[0] + 0x28;
        draw_beam_strand_with_glow(a, b, &beam_strands[k], 0x80, 0x40, i);
        draw_beam_strand_with_glow(a, b, &beam_strands[k1], 0x30, 0x10, i);
    }
}

