        FastVecScale(dn, hero_gravity_dir_r, -1.0f);
        qcopy(e, hero_gravity_dir_r - 0x210);
        qcopy(d + 0xA0, b);
        FastVecScale(d + 0x50, dn, FastVecDot(b, dn));
        clear_u64_value(d + 0xB0);
        clear_u64_value(d + 0xC0);
        clear_u64_value(d + 0xE0);
